+  world.add(sourceId, FloodState, {
+    remainingVolume: Math.max(0, volume - floodedTiles.length),
+    spreadPerTurn,
+    turnsLeft: turns,
+    frontier: [{ x, y }],
+    floodedTiles,
+  });
+  return true;
+}
